<?php
declare(strict_types=1);
function leave_can_manage(): bool {$u=team_identity();return $u&&($u['owner']||$u['group']==='manager');}
function leave_schema(): PDO {
 $db=payroll_schema();$db->exec("CREATE TABLE IF NOT EXISTS leave_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,date_from TEXT NOT NULL,date_to TEXT NOT NULL,reason TEXT NOT NULL,manager_note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS leave_dates ON leave_requests(date_from,date_to,user_id);CREATE TABLE IF NOT EXISTS leave_schedule_links(leave_id INTEGER NOT NULL,schedule_id INTEGER NOT NULL UNIQUE,PRIMARY KEY(leave_id,schedule_id))");
 // Keep previously recorded leave and its payroll link; ordinary work schedules stay intact.
 $old=$db->query("SELECT w.* FROM work_schedule w WHERE w.kind='leave' AND NOT EXISTS(SELECT 1 FROM leave_schedule_links l WHERE l.schedule_id=w.id)")->fetchAll();foreach($old as $s){$db->beginTransaction();try{$q=$db->prepare('SELECT 1 FROM leave_schedule_links WHERE schedule_id=?');$q->execute([$s['id']]);if(!$q->fetchColumn()){$db->prepare('INSERT INTO leave_requests(user_id,date_from,date_to,reason,manager_note,status,created_by,updated_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$s['user_id'],$s['date'],$s['date'],$s['note']?:'Lịch nghỉ đã ghi trước đây','',(int)$s['cancelled']?'cancelled':'approved',$s['actor'],$s['actor'],$s['created_at'],$s['created_at']]);$db->prepare('INSERT INTO leave_schedule_links(leave_id,schedule_id) VALUES(?,?)')->execute([(int)$db->lastInsertId(),$s['id']]);}$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}}
 return $db;
}
function leave_date($text): DateTimeImmutable {if(!is_string($text))throw new RuntimeException('Ngày nghỉ không hợp lệ.',400);$d=DateTimeImmutable::createFromFormat('!Y-m-d',$text,new DateTimeZone('Asia/Ho_Chi_Minh'));if(!$d||$d->format('Y-m-d')!==$text||!preg_match('/^20[0-9]{2}-/D',$text))throw new RuntimeException('Ngày nghỉ không hợp lệ.',400);return $d;}
function leave_sync(PDO $db,int $id,array $entry): void {
 $db->prepare('UPDATE work_schedule SET cancelled=1 WHERE id IN(SELECT schedule_id FROM leave_schedule_links WHERE leave_id=?)')->execute([$id]);if($entry['status']!=='approved')return;
 $end=leave_date($entry['date_to']);for($day=leave_date($entry['date_from']);$day<=$end;$day=$day->modify('+1 day')){$db->prepare("INSERT INTO work_schedule(user_id,date,start_min,end_min,lunch,kind,note,actor,created_at) VALUES(?,?,420,1110,11,'leave',?,?,?)")->execute([$entry['user_id'],$day->format('Y-m-d'),$entry['reason'],$entry['updated_by'],gmdate('c')]);$db->prepare('INSERT INTO leave_schedule_links(leave_id,schedule_id) VALUES(?,?)')->execute([$id,(int)$db->lastInsertId()]);}
}
function leave_save(array $data): array {
 $u=team_identity();if(!$u)throw new RuntimeException('Vui lòng đăng nhập.',401);$manage=leave_can_manage();$id=$data['id']??0;$version=$data['version']??0;if(!is_int($id)||$id<0||!is_int($version))throw new RuntimeException('Đề nghị không hợp lệ.',400);
 if(!$manage&&($id>0||isset($data['user_id'])&&(int)$data['user_id']!==$u['id']||isset($data['status'])&&$data['status']!=='pending'||!empty($data['manager_note'])))throw new RuntimeException('Nhân viên chỉ được gửi đề nghị nghỉ của mình; không được sửa hoặc duyệt lịch.',403);
 if(!is_string($data['reason']??null)||!is_string($data['manager_note']??''))throw new RuntimeException('Lý do và ghi chú phải là văn bản.',400);$uid=$manage?($data['user_id']??0):$u['id'];$from=leave_date($data['date_from']??null);$to=leave_date(($data['date_to']??'')?:($data['date_from']??null));$reason=trim((string)($data['reason']??''));$note=trim((string)($data['manager_note']??''));$status=$manage?($data['status']??'approved'):'pending';
 if(!is_int($uid)||$uid<1||$to<$from||$from->diff($to)->days>365||$reason===''||mb_strlen($reason)>1000||mb_strlen($note)>1000||!in_array($status,['pending','approved','rejected','cancelled'],true))throw new RuntimeException('Cần chọn nhân viên, ngày nghỉ và lý do hợp lệ.',400);
 if(!$manage&&$from<new DateTimeImmutable('today',new DateTimeZone('Asia/Ho_Chi_Minh')))throw new RuntimeException('Không gửi đề nghị cho ngày đã qua. Liên hệ quản lý để ghi bổ sung.',400);
 $db=leave_schema();$db->exec('BEGIN IMMEDIATE');try{$q=$db->prepare('SELECT 1 FROM staff WHERE id=?');$q->execute([$uid]);if(!$q->fetchColumn())throw new RuntimeException('Không tìm thấy nhân viên.',404);$old=null;if($id){$q=$db->prepare('SELECT * FROM leave_requests WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Không tìm thấy lịch nghỉ.',404);if((int)$old['version']!==$version)throw new RuntimeException('Lịch vừa được người khác cập nhật. Vui lòng xem lại trước khi lưu.',409);}
 if(in_array($status,['pending','approved'],true)){$q=$db->prepare("SELECT 1 FROM leave_requests WHERE user_id=? AND id<>? AND status IN ('pending','approved') AND date_from<=? AND date_to>=?");$q->execute([$uid,$id,$to->format('Y-m-d'),$from->format('Y-m-d')]);if($q->fetchColumn())throw new RuntimeException('Nhân viên đã có đề nghị hoặc lịch nghỉ trùng ngày.',409);}
 $now=gmdate('c');$entry=['user_id'=>$uid,'date_from'=>$from->format('Y-m-d'),'date_to'=>$to->format('Y-m-d'),'reason'=>$reason,'manager_note'=>$note,'status'=>$status,'updated_by'=>$u['username']];$args=array_values($entry);$args[]=$now;
 if($id){$args[]=$id;$db->prepare('UPDATE leave_requests SET user_id=?,date_from=?,date_to=?,reason=?,manager_note=?,status=?,updated_by=?,updated_at=?,version=version+1 WHERE id=?')->execute($args);}else{$args[]=$u['username'];$args[]=$now;$db->prepare('INSERT INTO leave_requests(user_id,date_from,date_to,reason,manager_note,status,updated_by,updated_at,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute($args);$id=(int)$db->lastInsertId();}
 leave_sync($db,$id,$entry);people_audit($old?'leave_update':($manage?'leave_record':'leave_request'),'Lịch nghỉ #'.$id,['before'=>$old,'after'=>$entry]);$db->exec('COMMIT');return ['id'=>$id,'version'=>$old?(int)$old['version']+1:1];
 }catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}
function leave_list(array $input): array {
 if(!team_identity())throw new RuntimeException('Vui lòng đăng nhập.',401);$month=$input['month']??'';[$from,$to]=people_month($month);$zone=new DateTimeZone('Asia/Ho_Chi_Minh');$a=(new DateTimeImmutable('@'.$from))->setTimezone($zone)->format('Y-m-d');$b=(new DateTimeImmutable('@'.$to))->setTimezone($zone)->format('Y-m-d');$uid=(int)($input['user']??0);$db=leave_schema();$sql='SELECT l.*,s.username,s.name,s.full_name FROM leave_requests l JOIN staff s ON s.id=l.user_id WHERE l.date_from<? AND l.date_to>=?';$args=[$b,$a];if($uid){$sql.=' AND l.user_id=?';$args[]=$uid;}$q=$db->prepare($sql.' ORDER BY l.date_from,l.user_id,l.id');$q->execute($args);return ['rows'=>$q->fetchAll(),'users'=>people_directory(),'canManage'=>leave_can_manage(),'self'=>team_identity()['id']];
}
